# sample config script to use speeddial module
#

# ----------- global configuration parameters ------------------------

check\_via=no	# (cmd. line: -v)
dns=no          # (cmd. line: -r)
rev\_dns=no      # (cmd. line: -R)

# ------------------ module loading ----------------------------------

mpath="/usr/local/lib/opensips/modules"
loadmodule "sl.so"
loadmodule "tm.so"
loadmodule "rr.so"
loadmodule "maxfwd.so"
loadmodule "usrloc.so"
loadmodule "registrar.so"
loadmodule "textops.so"
loadmodule "mysql.so"
loadmodule "speeddial.so"
loadmodule "mi\_fifo.so"

# ----------------- setting module-specific parameters ---------------

# -- mi\_fifo params --

modparam("mi\_fifo", "fifo\_name", "/tmp/opensips\_fifo")

# -- usrloc params --

modparam("usrloc", "db\_mode",   0)

# -------------------------  request routing logic -------------------

# main routing logic
route{

	# initial sanity checks 
	if (!mf\_process\_maxfwd\_header("10"))
	{
		sl\_send\_reply(483,"Too Many Hops");
		exit;
	};
	if ($ml >=  65535 )
	{
		sl\_send\_reply(513, "Message too big");
		exit;
	};

	if (!$rm=="REGISTER") record\_route();

	if (loose\_route())
	{
		if (!t\_relay())
		{
			sl\_reply\_error();
		};
		exit;
	};

	if (!is\_myself("$rd"))
	{
		if (!t\_relay())
		{
			sl\_reply\_error();
		};
		exit;
	};

	if (is\_myself("$rd"))
	{
		if ($rm=="REGISTER")
		{
			save("location");
			exit;
		};

		if($ru=~"sip:\[0-9\]{2}@.*")
			sd\_lookup("speeddial");

		lookup("aliases");
		if (!is\_myself("$rd"))
		{
			if (!t\_relay())
			{
				sl\_reply\_error();
			};
			exit;
		};

		if (!lookup("location"))
		{
			sl\_send\_reply(404, "Not Found");
			exit;
		};
	};

	if (!t\_relay())
	{
		sl\_reply\_error();
	};
}


